// Sound for the story ad: synthesised effects (nothing to credit), the music bed, and the final mix.
// Every effect is generated by ffmpeg from sine and noise sources, so there is no effects library.
import { execFileSync } from "node:child_process";
import { SFX, MUSIC_DIP, verticalToMain, CUT_VERTICAL } from "./from-a-chat.mjs";

// kind -> ffmpeg lavfi source chain producing one mono clip
export const SOUNDS = {
  whoosh: { dur: 0.7, src: "anoisesrc=d=0.7:c=pink:a=0.5,bandpass=f=900:w=1.4,afade=t=in:d=0.3,afade=t=out:st=0.3:d=0.4", vol: 0.9 },
  tick: { dur: 0.06, src: "sine=f=2100:d=0.06,afade=t=out:st=0.01:d=0.05", vol: 0.5 },
  tap: { dur: 0.09, src: "sine=f=900:d=0.09,afade=t=out:st=0.01:d=0.08", vol: 0.55 },
  bell: { dur: 1.6, src: "aevalsrc='0.5*sin(2*PI*1318*t)+0.3*sin(2*PI*1976*t)+0.2*sin(2*PI*2637*t)':d=1.6,afade=t=out:st=0.05:d=1.5", vol: 0.8 },
  ping: { dur: 0.7, src: "aevalsrc='0.6*sin(2*PI*1175*t)*lt(t,0.12)+0.6*sin(2*PI*1568*t)*gte(t,0.12)':d=0.7,afade=t=out:st=0.12:d=0.55", vol: 0.8 },
  chime: { dur: 1.4, src: "aevalsrc='0.4*sin(2*PI*1047*t)+0.35*sin(2*PI*1319*t)+0.3*sin(2*PI*1568*t)':d=1.4,afade=t=in:d=0.03,afade=t=out:st=0.1:d=1.3", vol: 0.9 },
  swell: { dur: 1.8, src: "anoisesrc=d=1.8:c=pink:a=0.6,lowpass=f=2400,afade=t=in:d=1.7", vol: 0.8 },
  murmur: { dur: 20, src: "anoisesrc=d=20:c=brown:a=0.9,lowpass=f=420,tremolo=f=3.1:d=0.45", vol: 0.5 },
};

/** Build the filter graph for the effects of one cut. `ranges` maps cut time to main-cut time. Returns {inputs, filters, labels}. */
export function sfxPlan(cut) {
  const map = (tMain) => {
    if (cut === "main") return tMain;
    let acc = 0;
    for (const r of CUT_VERTICAL) { if (tMain >= r.t0 && tMain < r.t1) return acc + (tMain - r.t0); acc += r.t1 - r.t0; }
    return null;
  };
  return SFX.map((c) => ({ ...c, at: map(c.t) })).filter((c) => c.at !== null);
}

export function buildAudio({ cut, music, offset = 0, out, duration, ranges }) {
  const cues = sfxPlan(cut);
  const inputs = [], filters = [], labels = [];
  let n = 0;
  const add = (src) => { inputs.push("-f", "lavfi", "-t", String(duration), "-i", src); return n++; };
  const base = add(`anullsrc=r=44100:cl=mono`);
  labels.push(`[${base}:a]`);
  cues.forEach((c, i) => {
    const s = SOUNDS[c.kind], d = Math.min(c.dur ?? s.dur, s.dur);
    const idx = add(s.src);
    filters.push(`[${idx}:a]atrim=0:${d},volume=${(s.vol * (c.gain ?? 1)).toFixed(2)},adelay=${Math.round(c.at * 1000)}:all=1[s${i}]`);
    labels.push(`[s${i}]`);
  });
  filters.push(`${labels.join("")}amix=inputs=${labels.length}:normalize=0:duration=first,aformat=sample_rates=44100:channel_layouts=stereo[fx]`);
  let last = "[fx]";
  if (music) {
    // The bed: the main cut plays the track from `offset`. The short cut plays the same track, one piece per range, so the music still lands on the payoff.
    const pieces = ranges.map((r, i) => {
      const t0 = cut === "main" ? r.t0 : r.t0, d = r.t1 - r.t0;
      return `[m]atrim=${(offset + t0).toFixed(3)}:${(offset + t0 + d).toFixed(3)},asetpts=PTS-STARTPTS,afade=t=in:d=0.15,afade=t=out:st=${(d - 0.25).toFixed(2)}:d=0.25[p${i}]`;
    });
    const dips = cut === "main" ? `,volume='if(between(t,${MUSIC_DIP.t0},${MUSIC_DIP.t1}),${MUSIC_DIP.level},1)':eval=frame` : "";
    inputs.push("-i", music);
    const mi = n++;
    filters.push(`[${mi}:a]aformat=sample_rates=44100:channel_layouts=stereo,asplit=${pieces.length}${pieces.map((_, i) => `[m${i}]`).join("")}`);
    const fixed = pieces.map((p, i) => p.replace("[m]", `[m${i}]`));
    filters.push(...fixed);
    filters.push(`${pieces.map((_, i) => `[p${i}]`).join("")}concat=n=${pieces.length}:v=0:a=1,volume=0.9${dips}[bed]`);
    filters.push(`[fx][bed]amix=inputs=2:normalize=0:duration=longest[mix]`);
    last = "[mix]";
  }
  filters.push(`${last}loudnorm=I=-14:TP=-1.5:LRA=11[o]`);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", ...inputs, "-filter_complex", filters.join(";"), "-map", "[o]", "-t", String(duration), "-ar", "44100", "-c:a", "aac", "-b:a", "192k", out]);
}
